using Payments;

namespace Payments.Tests;

/// <summary>
/// Fake implementation of IPaymentProvider for testing.
/// </summary>
internal sealed class FakePaymentProvider : IPaymentProvider
{
    public ChargeResult? ChargeResultToReturn { get; set; }
    public RefundResult? RefundResultToReturn { get; set; }
    public Exception? ExceptionToThrow { get; set; }

    public string? LastCardToken { get; private set; }
    public decimal? LastAmount { get; private set; }
    public string? LastChargeId { get; private set; }

    public Task<ChargeResult> ProcessChargeAsync(string cardToken, decimal amount)
    {
        if (ExceptionToThrow is not null) throw ExceptionToThrow;
        LastCardToken = cardToken;
        LastAmount = amount;
        return Task.FromResult(ChargeResultToReturn!);
    }

    public Task<RefundResult> ProcessRefundAsync(string chargeId)
    {
        if (ExceptionToThrow is not null) throw ExceptionToThrow;
        LastChargeId = chargeId;
        return Task.FromResult(RefundResultToReturn!);
    }
}

[TestClass]
public sealed class PaymentGatewayConstructorTests
{
    [TestMethod]
    public void Constructor_NullProvider_ThrowsArgumentNullException()
    {
        Assert.ThrowsException<ArgumentNullException>(() => new PaymentGateway(null!));
    }
}

[TestClass]
public sealed class ChargeAsyncTests
{
    private FakePaymentProvider _provider = null!;
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _provider = new FakePaymentProvider
        {
            ChargeResultToReturn = new ChargeResult("ch_123", true)
        };
        _gateway = new PaymentGateway(_provider);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessfulCharge()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 50.00m);

        Assert.IsNotNull(result);
        Assert.AreEqual("ch_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_PassesTokenAndAmountToProvider()
    {
        await _gateway.ChargeAsync("tok_abc", 99.95m);

        Assert.AreEqual("tok_abc", _provider.LastCardToken);
        Assert.AreEqual(99.95m, _provider.LastAmount);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderReturnsFailed_ReturnsFailedResult()
    {
        _provider.ChargeResultToReturn = new ChargeResult("ch_456", false);

        var result = await _gateway.ChargeAsync("tok_valid", 10.00m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? token)
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync(token!, 50.00m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_ExceedsMaxAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync("tok_valid", 1_000_000.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_ExactMaxAmount_Succeeds()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 999_999.99m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_SmallestPositiveAmount_Succeeds()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 0.01m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Network error");

        await Assert.ThrowsExceptionAsync<InvalidOperationException>(
            () => _gateway.ChargeAsync("tok_valid", 50.00m));
    }
}

[TestClass]
public sealed class RefundAsyncTests
{
    private FakePaymentProvider _provider = null!;
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _provider = new FakePaymentProvider
        {
            RefundResultToReturn = new RefundResult("rf_123", true)
        };
        _gateway = new PaymentGateway(_provider);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessfulRefund()
    {
        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsNotNull(result);
        Assert.AreEqual("rf_123", result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_PassesChargeIdToProvider()
    {
        await _gateway.RefundAsync("ch_abc");

        Assert.AreEqual("ch_abc", _provider.LastChargeId);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderReturnsFailed_ReturnsFailedResult()
    {
        _provider.RefundResultToReturn = new RefundResult("rf_456", false);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Timeout");

        await Assert.ThrowsExceptionAsync<InvalidOperationException>(
            () => _gateway.RefundAsync("ch_123"));
    }
}

[TestClass]
public sealed class ProcessWebhookTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new PaymentGateway(new FakePaymentProvider());
    }

    [TestMethod]
    [DataRow("charge.succeeded", "Charge succeeded")]
    [DataRow("charge.failed", "Charge failed")]
    [DataRow("refund.succeeded", "Refund succeeded")]
    [DataRow("charge.disputed", "Charge disputed")]
    public void ProcessWebhook_KnownEventType_ReturnsProcessed(string eventType, string expectedMessage)
    {
